using Xunit;using WinBgControlCenter.Core;namespace WinBgControlCenter.Core.Tests;
public sealed class ConfigValidatorTests{const string Safety="{\"schemaVersion\":\"1.0\",\"hardExclusions\":{\"processNames\":[\"lsass.exe\"],\"serviceNames\":[\"WinDefend\"],\"scheduledTaskPathPrefixes\":[\"\\\\Microsoft\\\\Windows\\\\\"]},\"forbiddenActions\":[\"RemoteWmi\",\"FirewallRuleChange\",\"PersistentDaemonInstall\",\"BrowserCompanionInstall\",\"BrowserExtensionDisable\",\"BrowserExtensionUninstall\",\"EtwMonitoringEnable\",\"AppxUninstall\",\"ExecutableQuarantine\",\"ExecutableMove\",\"RegistryClean\",\"DriverUpdate\",\"Overclock\",\"CloudLookup\",\"AutoApplyOptimization\"]}";const string Risk="{\"schemaVersion\":\"1.0\",\"defaultRiskClass\":\"NeedsUserDecision\",\"rules\":[{\"id\":\"r1\",\"targetKind\":\"StartupItem\",\"conditions\":{},\"riskClass\":\"NeedsUserDecision\",\"allowedActions\":[\"DisableStartupItem\"],\"reason\":\"ok\"}]}";const string Timeout="{\"schemaVersion\":\"1.0\",\"inventoryRefreshTimeoutMs\":1,\"timeoutMeansSafe\":false,\"blockActionsWhenRequiredEvidenceTimesOut\":true}";[Fact]public void ValidConfig_AllowsActions()=>Assert.True(new ConfigValidator().Validate(Safety,Risk,Timeout).ActionsAllowed);[Fact]public void EmptyHardExclusionProcessList_ForcesReadOnly()=>Assert.False(new ConfigValidator().Validate(Safety.Replace("[\"lsass.exe\"]","[]"),Risk,Timeout).ActionsAllowed);[Fact]public void MissingForbiddenAction_ForcesReadOnly()=>Assert.False(new ConfigValidator().Validate(Safety.Replace("\"RemoteWmi\",",""),Risk,Timeout).ActionsAllowed);[Fact]public void UnknownForbiddenAction_ForcesReadOnly()=>Assert.False(new ConfigValidator().Validate(Safety.Replace("AutoApplyOptimization\"","AutoApplyOptimization\",\"BadAction\""),Risk,Timeout).ActionsAllowed);[Fact]public void RiskRuleInvalidTargetKind_ForcesReadOnly()=>Assert.False(new ConfigValidator().Validate(Safety,Risk.Replace("StartupItem","BadKind"),Timeout).ActionsAllowed);[Fact]public void RiskRuleForbiddenAllowedAction_ForcesReadOnly()=>Assert.False(new ConfigValidator().Validate(Safety,Risk.Replace("DisableStartupItem","RemoteWmi"),Timeout).ActionsAllowed);[Fact]public void TimeoutLessThanOrEqualZero_ForcesReadOnly()=>Assert.False(new ConfigValidator().Validate(Safety,Risk,Timeout.Replace("\"inventoryRefreshTimeoutMs\":1","\"inventoryRefreshTimeoutMs\":0")).ActionsAllowed);[Fact]public void TimeoutMeansSafeTrue_ForcesReadOnly()=>Assert.False(new ConfigValidator().Validate(Safety,Risk,Timeout.Replace("\"timeoutMeansSafe\":false","\"timeoutMeansSafe\":true")).ActionsAllowed);[Fact]public void BlockActionsFalse_ForcesReadOnly()=>Assert.False(new ConfigValidator().Validate(Safety,Risk,Timeout.Replace("\"blockActionsWhenRequiredEvidenceTimesOut\":true","\"blockActionsWhenRequiredEvidenceTimesOut\":false")).ActionsAllowed);}
